package com.homa.conversation.domain;

import java.util.UUID;

/** A conversation's identity, generated by the domain. */
public record ConversationId(String value) {

    public ConversationId {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException("A conversation id must not be blank");
        }
    }

    public static ConversationId generate() {
        return new ConversationId(UUID.randomUUID().toString());
    }
}
